 <section v-if="loading" class="live-loading" role="status" aria-label="正在读取教学数据"><span/><span/><span/><p>正在同步教学数据…</p></section><section v-if="error" class="notice error" role="alert"><p>{{error}}</p><button @click="load">重新加载</button></section><p v-if="success" class="notice" role="status">{{success}}</p>
 <p v-if="actionError" class="notice error" role="alert">{{actionError}}</p><template v-if="!loading&&!error">
 <template v-if="mode==='classes'">
  <template v-if="!classId"><div v-if="teacher" class="section-heading"><h2>教学班</h2><button @click="classFormOpen=true">创建班级</button></div>

   <form v-if="!teacher" @submit.prevent="act(()=>teaching.join(inviteCode),'申请已提交，等待教师审核。')" class="form"><h2>加入班级</h2><label>班级邀请码<input v-model.trim="inviteCode" required maxlength="32" autocomplete="off" placeholder="向任课教师获取邀请码"/></label><p>提交前请核对邀请码。申请经教师审核后，才会收到班级任务。</p><button class="primary" :disabled="working">申请加入</button></form>
   <div v-if="classes.length&&teacher" class="insight-directory"><div class="insight-directory-tools"><label>搜索班级<input v-model="directorySearch" type="search" placeholder="输入班级名称或学期"/></label><div role="group" aria-label="班级展示方式"><button :aria-pressed="directoryLayout==='cards'" @click="directoryPreference='cards'">卡片展示</button><button :aria-pressed="directoryLayout==='list'" @click="directoryPreference='list'">折叠为列表</button></div></div><div class="live-class-grid insight-class-grid" :class="{'is-list':directoryLayout==='list'}"><article v-for="(c,index) in directoryClasses" :key="c.id" class="live-class-card insight-class-card" :class="'tone-'+index%3"><header class="insight-class-cover"><div><small>{{c.semester||'未设置学期'}}</small><h2><RouterLink :to="'/teacher/classes/'+c.id">{{c.name}}</RouterLink></h2><span class="status-tag" :class="c.archived?'neutral':'positive'">{{c.archived?'已归档':'使用中'}}</span></div><span class="insight-members-art" aria-hidden="true"/></header><div class="insight-class-body"><dl><div><dt>当前学生</dt><dd>{{c.joinedCount||0}}</dd></div><div><dt>待审核申请</dt><dd>{{c.pendingCount||0}}</dd></div></dl><p>{{c.archived?'班级已归档，历史训练与报告仍可查看。':c.pendingCount?'有新的加入申请，审核后学生可接收任务。':'管理班级成员、处理加入申请与安排教学任务。'}}</p><footer><RouterLink class="primary" :to="'/teacher/classes/'+c.id">管理班级</RouterLink><RouterLink :to="'/teacher/classes/'+c.id+'/members'">成员与邀请</RouterLink><RouterLink :to="{path:'/teacher/tasks',query:{classId:c.id}}">班级任务</RouterLink></footer></div></article></div><section v-if="!directoryClasses.length" class="live-empty"><h3>没有匹配的班级</h3><button @click="directorySearch=''">清除班级搜索</button></section></div>
   <div v-else-if="classes.length" class="table-scroll"><table><thead><tr><th>班级</th><th>学期</th><th>任课教师</th><th>状态</th></tr></thead><tbody><tr v-for="c in classes" :key="c.id"><td>{{c.name}}</td><td>{{c.semester}}</td><td>{{c.teacherName}}</td><td><span class="status-tag">{{c.archived?'已归档':memberLabel(c.state)}}</span></td></tr></tbody></table></div>
   <section v-else class="live-empty live-empty-bordered"><h3>{{teacher?'从第一个教学班开始':'你的班级会出现在这里'}}</h3><p>{{teacher?'创建班级、分享邀请码并审核学生申请，就能发布训练任务并跟进报告。':'向任课教师获取邀请码，提交申请后等待审核。'}}</p><button v-if="teacher" class="primary" @click="classFormOpen=true">创建教学班</button><ol v-if="teacher" class="empty-steps"><li>创建教学班</li><li>邀请并审核学生</li><li>发布训练任务</li></ol></section>
  </template>
  <template v-else-if="currentClass"><section class="live-panel live-detail"><h2>{{currentClass.name}}</h2><p>{{currentClass.semester}} · {{currentClass.archived?'已归档，历史保留':'邀请码：'+currentClass.inviteCode}}</p><div class="actions" v-if="!currentClass.archived"><button @click="editClassOpen=!editClassOpen">编辑班级</button><button @click="confirmAction('重置后原邀请码将失效。',()=>teaching.invite(classId),'邀请码已重置。')">重置邀请码</button><RouterLink class="primary" :to="{path:'/teacher/tasks/create',query:{classId}}">发布训练任务</RouterLink><button @click="confirmAction('归档将结束该班级已发布任务，历史报告保留。',()=>teaching.archive(classId),'班级已归档。')">归档班级</button></div><form v-if="editClassOpen" class="form" @submit.prevent="act(()=>teaching.editClass(classId,{name:currentClass.name,semester:currentClass.semester}),'班级资料已更新。')"><label>班级名称<input v-model="currentClass.name" required maxlength="80"/></label><label>学期<input v-model="currentClass.semester" required maxlength="80"/></label><button :disabled="working">保存班级</button></form>
   <TeachingExecutionOverview :assignments="currentClassAllocations"/><h2>成员申请与名单</h2><p>学生使用邀请码申请；审核通过后参与任务。移出保留已有任务与报告。</p><div v-if="members.length" class="table-scroll"><table><thead><tr><th>学生</th><th>账号</th><th>成员状态</th><th>操作</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td>{{m.name}}</td><td>{{m.username}}</td><td>{{memberLabel(m.state)}}</td><td><template v-if="m.state==='PENDING'&&!currentClass.archived"><button :disabled="working" @click="member(m,'JOINED')">通过申请</button><button :disabled="working" @click="member(m,'REJECTED')">拒绝申请</button></template><button v-if="m.state==='JOINED'&&!currentClass.archived" @click="confirmAction('移出后不能开始新的班级任务，历史保留。',()=>teaching.membership(classId,m.id,'REMOVED'),'成员已移出。')">移出班级</button></td></tr></tbody></table></div><section v-else class="live-empty"><h3>等待学生加入</h3><p>将上方邀请码分享给学生。学生提交申请后，可在这里审核并管理成员。</p><button @click="copyInvite">复制班级邀请码</button></section>
  </section></template><p v-else class="empty">班级不存在或你无访问权限。</p>
 </template>
 <StudentTeachingTasks v-else-if="mode==='tasks'&&!teacher" :tasks="tasks" :classes="classes" :assignment="assignment" :working="working" @retry="id=>act(()=>teaching.retry(id),'已重新生成报告，请稍后刷新。')"/>
 <template v-else-if="mode==='tasks'">
  <form v-if="teacher&&creatingTask" class="form task-form" @submit.prevent="createTask"><header class="task-editor-heading"><div><h1>{{editingTaskId?'编辑任务草稿':'创建训练任务'}}</h1><p>设置训练内容、完成要求与评价方案。</p></div><span class="status-tag">未发布草稿</span></header><div class="task-editor-layout"><div class="task-editor-main"><fieldset class="task-editor-section task-editor-basics"><legend>基本信息</legend><label>所属班级<select v-model.number="taskForm.classId" required :disabled="!!editingTaskId" @change="loadRecipients"><option value="">选择班级</option><option v-for="c in classes.filter(c=>!c.archived)" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>任务名称<input v-model.trim="taskForm.title" required maxlength="100"/></label><label class="task-description">任务说明<textarea v-model="taskForm.description" maxlength="2000" rows="3"/></label><label>目标岗位<select v-model.number="taskForm.jobId" required aria-label="目标岗位"><option value="">选择岗位</option><option v-for="j in jobs" :key="j.id" :value="j.id">{{j.name}}</option></select></label></fieldset><fieldset class="task-editor-section"><legend>训练内容与完成要求</legend><label>训练问题（每行一道，最多20道）<textarea v-model="questionText" required rows="6" maxlength="40000" placeholder="请介绍你的项目及职责。&#10;请说明关键技术方案的选择依据。"/></label><div class="form-grid"><label>时长<select v-model.number="taskForm.durationSeconds"><option :value="600">10分钟</option><option :value="900">15分钟</option><option :value="1200">20分钟</option><option :value="1800">30分钟</option></select></label><label>难度<select v-model.number="taskForm.difficulty"><option :value="1">基础</option><option :value="2">标准</option><option :value="3">进阶</option></select></label><label>开始时间<input v-model="taskForm.startTime" type="datetime-local" required/></label><label>截止时间<input v-model="taskForm.deadline" type="datetime-local" required/></label><label>最低有效次数<input v-model.number="taskForm.minAttempts" type="number" min="1" max="10" required/></label><label>最大训练次数<input v-model.number="taskForm.maxAttempts" type="number" :min="taskForm.minAttempts" max="20" required/></label></div><label class="check"><input v-model="taskForm.allowLate" type="checkbox"/>允许截止后完成训练</label></fieldset></div><aside class="task-editor-sidebar"><fieldset class="task-editor-section"><legend>参与学生</legend><label class="check"><input type="radio" v-model="taskForm.recipientMode" value="ALL" @change="taskForm.studentIds=[]"/>全班正常已加入成员</label><label class="check"><input type="radio" v-model="taskForm.recipientMode" value="SELECTED"/>指定学生（至少选择一人）</label><template v-if="taskForm.recipientMode==='SELECTED'"><label class="check" v-for="m in recipients.filter(m=>m.state==='JOINED'&&m.accountStatus===1)" :key="m.id"><input type="checkbox" v-model="taskForm.studentIds" :value="m.studentId"/>{{m.name}} · {{m.username}}</label></template></fieldset><fieldset class="task-editor-section"><legend>能力评价方案</legend><p>学生按此方案训练；发布后冻结，不受学生自主训练偏好影响。</p><TeachingScoreEditor v-model="taskForm.scoreModules"/></fieldset></aside></div><footer class="task-editor-footer"><p>保存为草稿后，可在任务详情中确认并发布。</p><button class="primary" :disabled="working">{{editingTaskId?'保存草稿修改':'保存任务草稿'}}</button></footer></form>
  <template v-else-if="teacher&&taskDetail"><section class="live-panel live-detail"><h2>{{taskDetail.title}}</h2><p>{{taskDetail.className}} · {{lifeLabel(taskDetail.lifecycle)}} · {{taskDetail.jobName}}</p><p>{{taskDetail.description}}</p><dl class="facts"><dt>截止时间</dt><dd>{{time(taskDetail.deadline)}}</dd><dt>训练要求</dt><dd>有效{{taskDetail.minAttempts}}次，最多{{taskDetail.maxAttempts}}次 · {{taskDetail.durationSeconds/60}}分钟 · {{taskDetail.allowLate?'允许逾期训练':'不允许逾期训练'}}</dd></dl><ol><li v-for="(text,i) in taskDetail.questions" :key="i">{{text}}</li></ol><div class="actions"><template v-if="taskDetail.lifecycle==='DRAFT'"><RouterLink :to="{path:'/teacher/tasks/'+taskDetail.id+'/edit',query:{returnTo:route.fullPath}}">编辑草稿</RouterLink><button :disabled="working" @click="confirmAction('删除未发布草稿后无法恢复。',async()=>{await teaching.discard(taskDetail.id);await router.push(back)},'草稿已删除。')">删除草稿</button></template><button v-if="taskDetail.lifecycle==='DRAFT'" class="primary" :disabled="working" @click="act(()=>teaching.publish(taskDetail.id),'任务已发布，学生已收到站内消息。')">发布任务</button><template v-else-if="!taskDetail.endedAt&&!taskDetail.archived"><button :disabled="working" @click="act(()=>teaching.remind(taskDetail.id),'提醒已发送给未完成且未减免的学生。')">提醒未完成学生</button><button @click="extendOpen=!extendOpen">延长截止时间</button><button @click="confirmAction('结束后不能开始新训练，历史报告保留。',()=>teaching.end(taskDetail.id),'任务已结束。')">结束任务</button></template></div><form class="form" v-if="extendOpen" @submit.prevent="act(()=>teaching.extend(taskDetail.id,newDeadline),'任务截止时间已更新。')"><label>新截止时间<input v-model="newDeadline" type="datetime-local" required/></label><p>个人截止优先；任务延期适用于未设置个人截止的参与学生。</p><button :disabled="working">保存延期</button></form><TeachingScorePlan :plan="taskDetail.scorePlan"/><TeachingAssignmentTools v-if="taskDetail.publishedAt&&!taskDetail.endedAt&&!taskDetail.archived" :task="taskDetail" :selected-assignment-id="route.query.assignmentId" @saved="success='补练安排已保存并通知学生。';load()"/><h2>学生执行与报告</h2><TeachingExecutionOverview :assignments="taskDetail.assignments"/><TaskManagementCharts v-if="taskDetail.publishedAt" :tasks="[taskDetail]"/><div v-if="route.query.execution||route.query.assignmentId" class="actions"><p>当前为来源页面指定的学生范围。</p><button @click="router.replace({query:{returnTo:route.query.returnTo}})">查看全部参与学生</button></div><div class="table-scroll"><table><thead><tr><th>学生</th><th>执行状态</th><th>有效次数</th><th>训练结果</th></tr></thead><tbody><tr v-for="a in visibleAssignments" :key="a.id"><td>{{a.name}}<small>{{a.username}}</small></td><td>{{assignmentLabel(a)}}</td><td>{{a.validCount}} / {{taskDetail.minAttempts}}</td><td><div v-for="p in a.attempts" :key="p.id">{{reportState(p.state)}} · {{p.submittedAt?time(p.submittedAt):'尚未提交'}} <RouterLink v-if="p.reportId" :to="reportLink(p.reportId)">查看报告并点评</RouterLink><small v-if="p.failureReason">{{p.failureReason}}</small></div><span v-if="!a.attempts.length">尚无训练结果</span></td></tr></tbody></table></div><p v-if="!visibleAssignments.length" class="empty">当前筛选内没有参与学生。</p></section></template>
  <template v-else><TaskListWorkbench :tasks="visibleTasks" :classes="classes" :loading="loading" @refresh="load"/></template>
 </template>
 <TeachingInbox v-else-if="mode==='messages'" :messages="messages" :teacher="teacher"/>
 <template v-else-if="mode==='students'"><h2>已加入的学生</h2><p>同一学生可加入多个班级；这里只显示你所管理的成员关系。</p><form class="live-filterbar" @submit.prevent><label>班级<select :value="route.query.classId||''" @change="router.replace({query:{...route.query,classId:$event.target.value||undefined}})"><option value="">全部班级</option><option v-for="c in classes" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label class="record-search">搜索学生<input type="search" :value="route.query.search||''" @input="router.replace({query:{...route.query,search:$event.target.value||undefined}})" placeholder="姓名或账号"/></label><button v-if="route.query.classId||route.query.classIds||route.query.semester||route.query.search" type="button" @click="router.replace({query:{returnTo:route.query.returnTo}})">清除筛选</button></form><p v-if="route.query.jobId" class="chart-caption">学生名单按班级成员关系展示；岗位筛选仅应用于下方教学任务与报告。</p><div v-if="visiblePeople.length" class="table-scroll"><table><thead><tr><th>学生</th><th>账号</th><th>班级</th><th>操作</th></tr></thead><tbody><tr v-for="s in visiblePeople" :key="s.classId+'-'+s.id"><td><RouterLink :to="{path:'/teacher/students/'+s.id,query:{classId:route.query.classId,classIds:route.query.classIds,semester:route.query.semester,jobId:route.query.jobId,returnTo:route.fullPath}}">{{s.name}}</RouterLink></td><td>{{s.username}}</td><td>{{s.className}}</td><td><RouterLink :to="{path:'/teacher/tasks',query:{classId:s.classId}}">查看班级任务</RouterLink></td></tr></tbody></table></div><section v-else class="live-empty live-empty-bordered"><h3>{{people.length?'当前范围没有匹配学生':'学生名单等待建立'}}</h3><p>创建教学班并分享邀请码，审核加入申请后，学生及其训练进展会显示在这里。</p><RouterLink class="primary" to="/teacher/classes">管理班级与邀请</RouterLink></section><template v-if="route.params.id"><section class="live-panel student-training-trend"><header><div><h2>近 30 天教学训练趋势</h2><p>只统计你分配给该学生的任务结果。</p></div></header><TeacherChart :points="studentTrend" :series="studentTasks.some(a=>a.attempts.length)?[{key:'valid',name:'有效训练'},{key:'invalid',name:'无效提交'}]:[]" :colors="['#059669','#b88740']" label="该学生近30天教学训练趋势"/><p v-if="!studentTasks.some(a=>a.attempts.length)" class="chart-caption">学生提交训练结果后，会在这里展示真实趋势。</p><TeachingExecutionOverview :assignments="studentTasks"/></section><h2>该学生的教学任务与报告</h2><article v-for="a in studentTasks" :key="a.id" class="result-row"><h3><RouterLink :to="{path:'/teacher/tasks/'+a.task.id,query:{returnTo:route.fullPath}}">{{a.task.title}}</RouterLink></h3><p>{{a.task.className}} · {{executionLabel(a.completionStatus)}} · 有效{{a.validCount}} / {{a.task.minAttempts}}次</p><p v-for="p in a.attempts" :key="p.id">{{reportState(p.state)}} <RouterLink v-if="p.reportId" :to="reportLink(p.reportId)">查看报告与点评 →</RouterLink></p></article><p v-if="!studentTasks.length" class="empty">没有你分配给该学生的已发布任务。</p></template></template>
 <TeachingOverview v-else-if="route.path==='/teacher/dashboard'" :classes="classes" :tasks="taskStats" :reports="reports" :people="people" :summary="summary" :report-load-error="reportLoadError" @reload="load"/>
 <TeachingAnalytics v-else-if="route.path.includes('analytics')" :classes="classes" :tasks="taskStats" :reports="reports" :people="people" :report-load-error="reportLoadError" @reload="load"/>
 <TeachingInsights v-else :classes="classes" :tasks="taskStats" :reports="reports" :summary="summary" :report-load-error="reportLoadError" @reload="load"/>

 </template>
<Teleport to="body"><dialog ref="classDialog" class="create-class-dialog" aria-labelledby="create-class-title" @cancel.prevent="closeClassDialog" @close="classFormOpen=false"><form @submit.prevent="createClass"><header><h2 id="create-class-title">创建教学班</h2><button type="button" aria-label="关闭创建班级" :disabled="working" @click="closeClassDialog">×</button></header><p>填写班级名称与学期，创建后即可邀请学生。</p><label>班级名称<input v-model.trim="classForm.name" autofocus required maxlength="80" placeholder="例如：软件2501" :disabled="working"/></label><label>学期<input v-model.trim="classForm.semester" required maxlength="80" placeholder="例如：2026–2027 第一学期" :disabled="working"/></label><p v-if="actionError" class="dialog-error" role="alert">{{actionError}}</p><footer><button type="button" :disabled="working" @click="closeClassDialog">取消</button><button class="primary" :disabled="working">{{working?'正在创建…':'创建班级'}}</button></footer></form></dialog></Teleport>
</main></AppLayout>
</template>
<script setup>
import {computed,ref,watch,nextTick} from 'vue'
import {inTeachingScope,validateTaskDraft,isOverdue,assignmentMatches} from '../services/teachingWorkspace.js'
import TeachingScoreEditor from '../components/teacher/TeachingScoreEditor.vue'
import TeachingScorePlan from '../components/teacher/TeachingScorePlan.vue'
import TeachingAssignmentTools from '../components/teacher/TeachingAssignmentTools.vue'
import StudentTeachingTasks from '../components/teacher/StudentTeachingTasks.vue'
import '../assets/styles/student-teaching.css'
import TeachingExecutionOverview from '../components/teacher/TeachingExecutionOverview.vue'
import TeacherChart from '../components/teacher/TeacherChart.vue'
import TeachingInbox from '../components/teacher/TeachingInbox.vue'
import TeachingInsights from '../components/teacher/TeachingInsights.vue'
import TaskListWorkbench from '../components/teacher/TaskListWorkbench.vue'
import TaskManagementCharts from '../components/teacher/TaskManagementCharts.vue'
import '../assets/styles/teacher-task-refresh.css'
import TeachingOverview from '../components/teacher/TeachingOverview.vue'
import TeachingAnalytics from '../components/teacher/TeachingAnalytics.vue'
import '../assets/styles/teaching-live.css'
import {useRoute,useRouter} from 'vue-router'
import AppLayout from '../components/layout/AppLayout.vue'
import {teaching} from '../services/teachingApi'
import {getJobList} from '../api'
import {safeTeacherReturn} from '../services/teacherContext'
const route=useRoute(),router=useRouter(),teacher=computed(()=>route.path.startsWith('/teacher')),mode=computed(()=>route.path.includes('messages')?'messages':route.path.includes('classes')?'classes':route.path.includes('tasks')?'tasks':route.path.includes('students')?'students':route.path.includes('reviews')?'reviews':'summary')
const title=computed(()=>({classes:teacher.value?'班级管理':'我的班级',tasks:teacher.value?'训练任务':'教学任务',messages:'教学消息',students:'学生名单',reviews:'教师待办中心',summary:route.path.includes('analytics')?'教学数据分析':route.path.includes('training-records')?'教学训练记录':route.path.includes('growth')?'教学成长记录':route.path.includes('activity')?'教学动态':'教学总览'}[mode.value])),classId=computed(()=>Number(route.params.classId)||0),creatingTask=computed(()=>route.path.endsWith('/tasks/create')||route.path.endsWith('/edit')),editingTaskId=computed(()=>route.path.endsWith('/edit')?Number(route.params.id):0),back=computed(()=>{
 const target=String(route.query.returnTo||'');if(teacher.value&&safeTeacherReturn(target))return safeTeacherReturn(target);
 if(!teacher.value&&/^\/my\/tasks(?:\?|$)/.test(target))return target;
 return teacher.value?mode.value==='classes'?'/teacher/classes':mode.value==='students'?'/teacher/students':'/teacher/tasks':'/my/tasks'
})
const reportLoadError=ref(false)
