async function loadTaskDataset(){
 const all=await teaching.tasks({includeAssignments:true});
 // Compatibility with older servers: progress is unavailable until authorized task details arrive.
 return Promise.all(all.map(t=>t.publishedAt&&!Array.isArray(t.assignments)?teaching.task(t.id):t))
}
let generation=0
async function load(){
 const own=++generation,currentMode=mode.value,id=route.params.id,cid=classId.value,creating=creatingTask.value;
 loading.value=true;error.value='';reportLoadError.value=false;
 try{
  const list=await teaching.classes();if(own!==generation)return;
  classes.value=list;taskDetail.value=null;assignment.value=null;filterClass.value=String(route.query.classId||'');
  if(currentMode==='classes'){
   if(cid){const result=await teaching.members(cid),all=await teaching.tasks(),details=await Promise.all(all.filter(t=>t.publishedAt&&Number(t.classId)===cid).map(t=>teaching.task(t.id)));if(own===generation){members.value=result;taskStats.value=details}}
  }else if(currentMode==='tasks'){
   if(creating){
    const result=await getJobList();if(own!==generation)return;jobs.value=result;
    if(editingTaskId.value){const draft=await teaching.task(editingTaskId.value);if(own!==generation)return;if(draft.lifecycle!=='DRAFT')throw Error('已发布任务的内容已冻结，请返回任务详情延期或结束。');for(const key of Object.keys(taskForm.value))if(key in draft)taskForm.value[key]=draft[key];taskForm.value.startTime=draft.startTime.slice(0,16);taskForm.value.deadline=draft.deadline.slice(0,16);taskForm.value.scoreModules=draft.scorePlan?.modules?.map(m=>({code:m.code,rank:m.rank,level:m.level}))||[];questionText.value=draft.questions.join('\n');await loadRecipients();taskForm.value.studentIds=draft.assignments.map(a=>a.studentId);taskForm.value.recipientMode='SELECTED'}
    else{taskForm.value.classId=Number(route.query.classId)||taskForm.value.classId;await loadRecipients();const requested=String(route.query.studentIds||'').split(',').filter(Boolean).map(Number);if(requested.length){taskForm.value.studentIds=requested.filter(id=>recipients.value.some(m=>m.studentId===id&&m.state==='JOINED'&&m.accountStatus===1));taskForm.value.recipientMode='SELECTED';if(taskForm.value.studentIds.length!==requested.length)actionError.value='部分所选学生已不可参与，请核对名单。'}if(route.query.abilityCode)success.value='来自分析页面的建议维度：'+route.query.abilityCode+'。请配置完整评价方案。'}
   }
   else if(id){const result=await (teacher.value?teaching.task(id):teaching.assignment(id));if(own===generation){if(teacher.value)taskDetail.value=result;else assignment.value=result}}
   else{const result=await (teacher.value?loadTaskDataset():teaching.mine());if(own===generation)tasks.value=result}
  }else if(currentMode==='students'){const result=await teaching.people();let details=[];if(id){const all=await loadTaskDataset();details=all.filter(t=>t.publishedAt)}if(own===generation){people.value=result.filter(s=>!id||String(s.id)===String(id));taskStats.value=details}}
  else if(currentMode==='messages'){const result=await teaching.messages();if(own===generation)messages.value=result}
  else{
   const [counts,all,roster]=await Promise.all([teaching.summary(),loadTaskDataset(),teaching.people()]),details=all.filter(t=>t.publishedAt);
   let result=details.flatMap(t=>t.assignments.flatMap(a=>a.attempts.filter(p=>p.reportId).map(p=>({...p,name:a.name,studentId:a.studentId,title:t.title,taskId:t.id,classId:t.classId,className:t.className,jobId:t.jobId,jobName:t.jobName}))));
   if(route.path.includes('analytics')||route.path==='/teacher/dashboard'){const loaded=[];for(let offset=0;offset<result.length;offset+=4){loaded.push(...await Promise.allSettled(result.slice(offset,offset+4).map(async p=>({...p,detailReport:(await teaching.report(p.reportId)).report}))));if(own!==generation)return;}if(own!==generation)return;reportLoadError.value=loaded.some(r=>r.status==='rejected');result=loaded.map((r,i)=>r.status==='fulfilled'?r.value:result[i])}
